void handle_char(int c, int is_zero) {

    switch (c) {
        case '0':
            if (is_zero == true) {
                break;
            } else {
                putchar(c);
                is_zero = false;
                break;
            }
        case ' ':
            putchar(c);
            is_zero = true;
            break;
        case '\n':
            putchar(c);
            is_zero = true;
            break;
        default:
            putchar(c);
            is_zero = false;
            break;
    }

}

