int charToDecimal(char c) {
    return (9 - (57 % (int)c));
}

int strToInt(char lastDigit) {
    char c;
    int num = charToDecimal(lastDigit);
    while((c = getchar()) != EOF && c != ' ' && c != '\n') {
        c = charToDecimal(c);
        num = num * 10 + c;
    }
    return num;
}

