#define MAX 100

void imprime(char s[])
{
    int i, flag = 0;
    for(i = 0; s[i] != '\0' && i < (int) strlen(s); i++){
        if(s[i] != '0' || flag) {
            putchar(s[i]);
            flag = 1;
        }
    }
    if(flag == 0)
        putchar(s[0]);
}

