{
    int c, i = 0;
    char numero[MAX];
    while((c = getchar()) != EOF) {
        if(c == ' ' || c == '\n'){
            numero[i] = '\0';
            imprime(numero);
            putchar(' ');
            i = 0;
        }
        else {
            numero[i] = c;
            i++;
        }
    }
    numero[i] = '\0';
    imprime(numero);
    putchar('\n');
