    char seq[SEQ], c;
    int i = 0, zero_inicial = 1;

    while (i < SEQ - 1 && (c = getchar()) != EOF) 
        seq[i++] = c;

    seq[i] = '\0';
    printf("\n");

    for (i = 0; seq[i] != '\0'; i++) {
        if (zero_inicial && seq[i] == '0') {
            if (seq[i + 1] == '\n' || seq[i + 1] == '\0' || seq[i + 1] == ' ') {
                putchar(seq[i]);
                zero_inicial = 0; 
            }
        }

        else if (seq[i] > '0' && seq[i] <= '9') {
            putchar(seq[i]); 
            zero_inicial = 0; 
        }
        else {
            putchar(seq[i]); 
            zero_inicial = 1;
        }
    }
    return 0;
}

